     5→interface ArrowAnnotationProps {
     6→  annotation: Annotation;
     7→}
     8→
     9→/**
    10→ * ArrowAnnotation Component
    11→ *
    12→ * Renders a directional arrow between two points on the 3D field.
    13→ * The arrow consists of a line segment with a cone arrowhead at the end point.
    14→ */
    15→export function ArrowAnnotation({ annotation }: ArrowAnnotationProps) {
    16→  const coneRef = useRef<Mesh>(null);
    17→
    18→  // Validate annotation has at least 2 points for start and end
    19→  if (annotation.points.length < 2) {
    20→    return null;
    21→  }
    22→
    23→  const startPoint = annotation.points[0];
    24→  const endPoint = annotation.points[1];
    25→
    26→  // Memoize line geometry points
    27→  const linePoints = useMemo(() => {
    28→    return new Float32Array([
    29→      startPoint[0], startPoint[1], startPoint[2],
    30→      endPoint[0], endPoint[1], endPoint[2],
    31→    ]);
    32→  }, [startPoint, endPoint]);
    33→
    34→  // Calculate cone rotation to point from start to end
    35→  const coneRotation = useMemo(() => {
    36→    const start = new Vector3(startPoint[0], startPoint[1], startPoint[2]);
    37→    const end = new Vector3(endPoint[0], endPoint[1], endPoint[2]);
    38→
    39→    // Direction vector from start to end
    40→    const direction = new Vector3().subVectors(end, start).normalize();
    41→
    42→    // Cone default direction is along positive Y-axis
    43→    // We need to rotate it to align with our direction vector
    44→    // Using spherical coordinates to calculate rotation
    45→    const phi = Math.acos(direction.y); // Angle from Y-axis
    46→    const theta = Math.atan2(direction.x, direction.z); // Rotation around Y-axis
    47→
    48→    // Euler rotation: first rotate around X to tilt, then around Y to point direction
    49→    return new Euler(phi, theta, 0, 'YXZ');
    50→  }, [startPoint, endPoint]);
    51→
    52→  // Arrowhead cone dimensions - scaled appropriately for field visibility
    53→  const coneRadius = 0.8;
    54→  const coneHeight = 2.0;
    55→  const coneSegments = 8;
    56→
    57→  // Offset the cone slightly back along the arrow so tip is exactly at endpoint
    58→  const conePosition = useMemo(() => {
    59→    const start = new Vector3(startPoint[0], startPoint[1], startPoint[2]);
    60→    const end = new Vector3(endPoint[0], endPoint[1], endPoint[2]);
    61→
    62→    // Direction vector from start to end
    63→    const direction = new Vector3().subVectors(end, start).normalize();
    64→
    65→    // Move cone back by half its height so the tip is at the endpoint
    66→    const offset = direction.multiplyScalar(-coneHeight / 2);
    67→
    68→    return [
    69→      endPoint[0] + offset.x,
    70→      endPoint[1] + offset.y,
    71→      endPoint[2] + offset.z,
    72→    ] as [number, number, number];
    73→  }, [startPoint, endPoint, coneHeight]);
    74→
    75→  return (
    76→    <group>
    77→      {/* Arrow line segment */}
    78→      <line>
    79→        <bufferGeometry>
    80→          <bufferAttribute
    81→            attach="attributes-position"
    82→            count={2}
    83→            array={linePoints}
    84→            itemSize={3}
    85→          />
    86→        </bufferGeometry>
    87→        <lineBasicMaterial color={annotation.color} linewidth={annotation.thickness || 2} />
    88→      </line>
    89→
    90→      {/* Arrowhead cone at end point */}
    91→      <mesh
    92→        ref={coneRef}
    93→        position={conePosition}
    94→        rotation={coneRotation}
    95→      >
    96→        <coneGeometry args={[coneRadius, coneHeight, coneSegments]} />
    97→        <meshStandardMaterial color={annotation.color} />
    98→      </mesh>
    99→    </group>
